function bestChapter(key,title,book){
 if(!book||!book.chapters)return null;
 const n=norm(title),hints=H[key]||[];
 let target="";
 for(const h of hints){if(n.includes(norm(h[0]))){target=h[1];break;}}
 const items=book.chapters.map(function(c){
  const head=norm(c[0]),words=n.split(" ").filter(x=>x.length>2);
  let score=words.reduce((z,w)=>z+(head.includes(w)?2:0),0);
  if(target&&head.includes(norm(target)))score+=12;
  if(target&&norm(target).split(" ").some(w=>w.length>3&&head.includes(w)))score+=5;
  return {chapter:c,score:score};
 }).sort(function(a,b){return b.score-a.score;});
 return items.length&&items[0].score>0?items[0].chapter:null;
}
